document.addEventListener("DOMContentLoaded",initRecentPage);function initRecentPage(){wireRecentTabs();document.getElementById("recent-clear").addEventListener("click",()=>{if(!window.confirm("Clear your recently viewed products and stores on this phone?"))return;clearRecentViews();renderRecent();document.getElementById("recent-status").textContent="History cleared."});if(getQueryParam("tab")==="stores")selectRecentTab("stores",false);renderRecent()}function viewedAgo(at){const t=Number(at);if(!t)return"";const mins=Math.floor((Date.now()-t)/6e4);if(mins<1)return"Just now";if(mins<60)return mins+" min ago";const hours=Math.floor(mins/60);if(hours<24)return hours+(hours===1?" hour ago":" hours ago");const days=Math.floor(hours/24);if(days===1)return"Yesterday";if(days<7)return days+" days ago";return new Date(t).toLocaleDateString(undefined,{day:"numeric",month:"short"})}const RECENT_TYPE_LABEL={rental:"Rental",service:"Service"};function recentThumb(url,alt){const src=url?optimizedImageUrl(url,IMG_W.thumb):"";return/^https:\/\//i.test(src)?'<img class="recent-thumb" src="'+escapeAttr(src)+'" alt="" loading="lazy" decoding="async" width="64" height="64">':'<span class="recent-thumb recent-thumb--blank" aria-hidden="true"></span>'}function productRow(p){const href="product.html?store="+encodeURIComponent(p.storeSlug)+"&product="+encodeURIComponent(p.id);const place=storeLocationLabel(p.island,p.village);const kind=RECENT_TYPE_LABEL[p.listingType];return'<li><a class="recent-item" href="'+escapeAttr(href)+'">'+recentThumb(p.imageUrl)+'<span class="recent-text">'+'<span class="recent-name">'+escapeHtml(p.name||"Product")+"</span>"+'<span class="recent-meta">'+escapeHtml([kind,p.storeName,place].filter(Boolean).join(" · "))+"</span>"+'<span class="recent-when">'+escapeHtml(viewedAgo(p.at))+"</span>"+"</span></a></li>"}function storeRow(s){const href="store.html?store="+encodeURIComponent(s.id);const place=storeLocationLabel(s.island,s.village);return'<li><a class="recent-item" href="'+escapeAttr(href)+'">'+recentThumb(s.logoUrl)+'<span class="recent-text">'+'<span class="recent-name">'+escapeHtml(s.name||"Store")+"</span>"+(place?'<span class="recent-meta">'+escapeHtml(place)+"</span>":"")+'<span class="recent-when">'+escapeHtml(viewedAgo(s.at))+"</span>"+"</span></a></li>"}function emptyRow(what,href,label){return'<li class="recent-empty"><p>No '+what+" viewed yet on this phone.</p>"+'<p><a class="btn btn-light-purple" href="'+href+'">'+label+"</a></p></li>"}function renderRecent(){const products=getRecentProducts();const stores=getRecentStores();document.getElementById("recent-products").innerHTML=products.length?products.map(productRow).join(""):emptyRow("products","categories.html","Browse Categories");document.getElementById("recent-stores").innerHTML=stores.length?stores.map(storeRow).join(""):emptyRow("stores","stores.html","Browse Stores");document.getElementById("recent-count-products").textContent=products.length?"("+products.length+")":"";document.getElementById("recent-count-stores").textContent=stores.length?"("+stores.length+")":"";document.getElementById("recent-clear").hidden=!products.length&&!stores.length}function selectRecentTab(which,focus){["products","stores"].forEach(name=>{const tab=document.getElementById("recent-tab-"+name);const on=name===which;tab.setAttribute("aria-selected",on?"true":"false");tab.tabIndex=on?0:-1;document.getElementById("recent-panel-"+name).hidden=!on;if(on&&focus)tab.focus()})}function wireRecentTabs(){const tabs=["products","stores"];tabs.forEach((name,i)=>{const tab=document.getElementById("recent-tab-"+name);tab.addEventListener("click",()=>selectRecentTab(name,false));tab.addEventListener("keydown",e=>{if(e.key!=="ArrowRight"&&e.key!=="ArrowLeft")return;e.preventDefault();selectRecentTab(tabs[(i+(e.key==="ArrowRight"?1:tabs.length-1))%tabs.length],true)})})}